        Post::create([
            'category_id' => 3,
            'user_id' => 1,
            'title' => 'Poem #11',
            'description' => '<p style="text-align:center;">"No Internet Is Such A Dull Day"</p>
            <p style="text-align:left;">I.</p>
                <p style="margin-left:2em;">The internet is the source of everything</p>
                <p style="margin-left:2em;">Games, references, tutorials, just about anything</p>
                <p style="margin-left:2em;">Search the web in a single click</p>
                <p style="margin-left:2em;">No, it\'s not some sort of magic trick</p>
